target.css:
:root {
  --ink: #24423a;
  --leaf: #3d8a63;
  --mint: #dff3df;
  --cream: #fffdf4;
  --line: #b9d7c1;
}

* {
  box-sizing: border-box;
}

.adoption-card {
  width: 440px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--cream);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--mint);
}

.sprout {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--cream);
  font-size: 22px;
}

.card-header section {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--leaf);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--leaf);
  color: var(--cream);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.details {
  display: flex;
  gap: 10px;
  padding: 14px 16px;
}

.details p {
  flex: 1;
  margin: 0;
}

.details span,
footer span {
  display: block;
  color: var(--leaf);
  font-size: 11px;
  font-weight: 700;
}

.details strong {
  display: block;
  margin-top: 3px;
  font-size: 14px;
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

button {
  border: 0;
  border-radius: 8px;
  padding: 7px 12px;
  background: var(--leaf);
  color: var(--cream);
  font-size: 12px;
  font-weight: 700;
}

